#include <bits/stdc++.h>
using namespace std;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> lines;
    string line;
    // 读取所有输入行
    for (; getline(cin, line);)
    {
        lines.push_back(line);
    }
    // 删除末尾空行
    while (!lines.empty() && lines.back().empty())
    {
        lines.pop_back();
    }

    int n = 0, m = 0;
    string a, b;
    {
        stringstream ss(lines[0]);
        vector<string> t;
        string x;
        while (ss >> x)
        {
            t.push_back(x);
        }

        if (t.size() == 2)
        {
            n = stoi(t[0]);
            m = stoi(t[1]);
            if (lines.size() > 1) a = lines[1];
            if (lines.size() > 2) b = lines[2];
        }
        else
        {
            n = stoi(t[0]);
            if (lines.size() > 1) a = lines[1];
            if (lines.size() > 2) m = stoi(lines[2]);
            if (lines.size() > 3) b = lines[3];
        }
    }

    vector<vector<int>> dp(n + 1, vector<int>(m + 1));
    // 边界初始化
    for (int i = 0; i <= n; ++i)
    {
        dp[i][0] = i;
    }
    for (int j = 0; j <= m; ++j)
    {
        dp[0][j] = j;
    }

    // 编辑距离DP核心
    for (int i = 1; i <= n; ++i)
    {
        for (int j = 1; j <= m; ++j)
        {
            dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1);
            dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + (a[i - 1] != b[j - 1]));
        }
    }

    cout << dp[n][m] << "\n";
    return 0;
}
